{v:'VER',what:'party2, his yes to arcade power-ups (40): kills drop timed pickups at a low rate from a side stream (the same raid drops the same ones and the main stream does not move); walking over one takes it; BOTTOMLESS CLIP keeps the magazine full and the trigger live with nothing in reserve; DOUBLE DAMAGE doubles a round; RAPID FIRE shortens the trigger gap; the coin, the ring and a timer chip are drawn',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep&&window.__sim)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof ARCADE!=='object') return 'SKIP: no arcade here';
   var bad=[], g=null, p, own=false, rs=say, oWep, oAmmo, oRes, i, S, last, log1, log2, n1, s0, s1, kinds={}, d1, d2, c1, c2, arcs=[], txts=[], proto, oArc, oFt, sp, hit;
   function step(n){ var q; for(q=0;q<n;q++){ g.t+=0.016; __sim(0.016); } }
   function arm(w,a,r){ mouse.down=false; p.wep=w; p.ammo=a; p.reserve=r; p.reloading=0; p.hand=false; p.jam=0; p.fired=false; p.spin=0; g.t+=0.016; __sim(0.016); for(var q=0;q<260&&p.drawT>0;q++){ g.t+=0.016; __sim(0.016); } p.lastShot=-1e9; p.fired=false; g.bullets.length=0; }
